<?php
namespace App\Http\Controllers; use App\Models\EstadoCuenta; use App\Models\Pago; use App\Services\RecaudoService; class EstadoCuentaController extends CrudController {protected $service;protected $model=EstadoCuenta::class;public function __construct(RecaudoService $service){$this->service=$service;}protected function rules():array{return ['inmueble_id'=>'required|integer','periodo_mes'=>'required|integer|between:1,12','periodo_anio'=>'required|integer','fecha_vencimiento'=>'required|date'];}}
class PagoController extends CrudController {protected $service;protected $model=Pago::class;public function __construct(RecaudoService $service){$this->service=$service;}protected function rules():array{return ['inmueble_id'=>'required|integer','fecha_pago'=>'required|date','valor_transferido'=>'required|numeric','medio_pago_id'=>'required|integer','registrado_por'=>'required|integer'];}}
